{
  "aggregate_id": "DEF-NRS-484A-125::moped",
  "classifications": [
    {
      "class": "ru.bicycle",
      "verdict": "supported",
      "reason": "The contract describes human-powered devices, which the nested vehicle definition excepts and the quoted engine-propulsion requirement does not admit."
    },
    {
      "class": "ru.bus",
      "verdict": "underdetermined",
      "reason": "The bus contract specifies passenger capacity but no wheel count, so the quoted three-wheel ceiling does not exclude every member."
    },
    {
      "class": "ru.child",
      "verdict": "supported",
      "reason": "The contract describes persons, whereas the admitting words describe motor-driven devices."
    },
    {
      "class": "ru.commercial_motor_vehicle",
      "verdict": "underdetermined",
      "reason": "Neither the commercial contract nor the statutory ceiling on wheels in contact guarantees that every admitted member is a two- or three-wheeler satisfying the ru.moped contract."
    },
    {
      "class": "ru.electric_bicycle",
      "verdict": "underdetermined",
      "reason": "The contract does not require the statutory electric-bicycle power and assistance limits, so the defined-term exception does not establish exclusion of the entire class."
    },
    {
      "class": "ru.electric_scooter",
      "verdict": "supported",
      "reason": "The contract omits the statutory weight and speed limits, allowing both excluded electric scooters and other scooters potentially satisfying the moped definition without guaranteed coverage."
    },
    {
      "class": "ru.emergency_vehicle",
      "verdict": "underdetermined",
      "reason": "Emergency designation imposes no wheel count, and the admitting words do not guarantee that every admitted member satisfies the two- or three-wheeler requirement of ru.moped."
    },
    {
      "class": "ru.fire_apparatus",
      "verdict": "underdetermined",
      "reason": "The fire-fighting contract supplies no minimum wheel count that would place every member outside the quoted ceiling."
    },
    {
      "class": "ru.moped",
      "verdict": "supported",
      "reason": "The contract expressly follows the jurisdiction's moped classification, and the posted definition supplies the admitting engine, wheel and speed requirements."
    },
    {
      "class": "ru.motor_vehicle",
      "verdict": "underdetermined",
      "reason": "The contract excludes separately classified powered two-wheelers but does not exclude all other self-propelled configurations that the moped definition can admit."
    },
    {
      "class": "ru.motorcycle",
      "verdict": "contradicted",
      "reason": "The words admit qualifying motor-driven cycles, and admitted motorcycles have the two- or three-wheeled small-engine characteristics and jurisdictional classification required by ru.moped."
    },
    {
      "class": "ru.official_vehicle",
      "verdict": "underdetermined",
      "reason": "Official service and identifying equipment do not establish that every admitted member is a two- or three-wheeler carrying ru.moped."
    },
    {
      "class": "ru.pedestrian",
      "verdict": "supported",
      "reason": "The contract describes persons rather than the motor-driven devices admitted by the definition."
    },
    {
      "class": "ru.pedestrian_with_white_cane_or_guide_animal",
      "verdict": "supported",
      "reason": "The contract describes pedestrians with specified assistance, not motor-driven devices."
    },
    {
      "class": "ru.rail_vehicle",
      "verdict": "underdetermined",
      "reason": "The vehicle exception requires exclusive use upon stationary rails, whereas the class contract describes on-track equipment without requiring exclusive rail use."
    },
    {
      "class": "ru.school_bus",
      "verdict": "underdetermined",
      "reason": "School designation and markings impose no wheel count, so the quoted ceiling does not establish exclusion."
    },
    {
      "class": "ru.taxicab",
      "verdict": "underdetermined",
      "reason": "The passenger-for-hire contract imposes no wheel count, leaving admitted configurations that the proposed two- or three-wheeler covering contract does not establish it covers."
    },
    {
      "class": "ru.tour_bus_or_limousine",
      "verdict": "underdetermined",
      "reason": "Neither branch of the contract specifies a wheel count exceeding the statutory ceiling."
    },
    {
      "class": "ru.trailer_or_combination",
      "verdict": "underdetermined",
      "reason": "Although a drawn trailer need not be engine-propelled, the contract also includes combinations that the quoted propulsion requirement does not categorically exclude."
    },
    {
      "class": "ru.transit_bus",
      "verdict": "underdetermined",
      "reason": "Public-transit service and identifying displays impose no wheel count that establishes exclusion under the quoted ceiling."
    },
    {
      "class": "ru.truck",
      "verdict": "underdetermined",
      "reason": "A goods-carrying body does not require more than three wheels under the class contract, so the quoted limitation does not exclude every member."
    }
  ]
}

